let exit = match self.process.as_mut() {
    Some(process) => process.poll_exit(),
    None => return,
};
match exit {
    Ok(None) => context.request_repaint_after(std::time::Duration::from_millis(100)),
    Ok(Some(status)) => {
        self.process = None;
        let purpose = self
            .process_purpose
            .take()
            .unwrap_or(ExternalAgentPurpose::BuildOrRepair);
        if status.success() {
            self.provider_failure_hint = None;
            match purpose {
                ExternalAgentPurpose::BuildOrRepair => {
                    self.finish_provider_execution(&run_id, status.code());
                }
                ExternalAgentPurpose::RuntimeEvaluation => {
                    self.finish_runtime_evaluation(&run_id, status.code());
                }
            }
        } else {
            let message = if provider_kind == ExternalAgentProviderKind::Generic {
                format!(
                    "External agent exited unsuccessfully with {:?}.",
                    status.code()
                )
            } else {
                self.provider_failure_hint
                    .take()
                    .unwrap_or_else(ProviderFailureHint::execution_failed)
                    .message(provider_kind)
            };
            match purpose {
                ExternalAgentPurpose::BuildOrRepair => self.fail_run(&run_id, message),
                ExternalAgentPurpose::RuntimeEvaluation => {
                    self.record_runtime_evaluation_failure(&run_id, message);
                }
            }
        }
    }
    Err(error) => {
        self.process = None;
        let purpose = self
            .process_purpose
            .take()
            .unwrap_or(ExternalAgentPurpose::BuildOrRepair);
        let message = if provider_kind == ExternalAgentProviderKind::Generic {
            format!("Could not poll external agent: {error}")
        } else {
            ProviderFailureHint::execution_failed().message(provider_kind)
        };
        match purpose {
            ExternalAgentPurpose::BuildOrRepair => self.fail_run(&run_id, message),
            ExternalAgentPurpose::RuntimeEvaluation => {
                self.record_runtime_evaluation_failure(&run_id, message);
            }
        }
    }
}
